('persist-solution-id-github-var', 'Persisting solution ID as GitHub repo variable', 'Set DEV_SOLUTION_ID (the solutionid GUID captured from create-publisher-solution) as a GitHub repository variable via gh variable set. Same rationale as the environment GUIDs: system-generated, not a name we chose, so it does not belong in a committed file. Ask-first since this touches GitHub repo settings.');

INSERT INTO todo_deps (todo_id, depends_on) VALUES
('persist-solution-id-github-var', 'create-publisher-solution'),
('clone-solution-locally', 'persist-solution-id-github-var'),
('document-conventions', 'persist-solution-id-github-var');

UPDATE todos SET description = 'Confirm exact environment ID/URL/region for the "Raphael Pothin" Sandbox environment (36f603f9-0af2-e33d-98a5-64b02c1bac19) via pac/dv-solution tooling before any write operation.' WHERE id = 'resolve-dev-env';

UPDATE todos SET description = 'Set DEV_ENVIRONMENT_URL and DEV_ENVIRONMENT_ID as GitHub repository variables using: gh variable set DEV_ENVIRONMENT_URL --body "<url>" --repo rpothin/mcdm26-ai-native-powerplatform-dev (and same for DEV_ENVIRONMENT_ID); verify with gh variable list. Both formats are needed: pac/dv-solution auth expects the environment URL, while flowagent/Power Automate tooling expects the environment ID (GUID) directly. Never write the ID/URL into tracked repo files. Ask-first since this touches GitHub repo settings.' WHERE id = 'persist-env-github-vars';

UPDATE todos SET description = 'Set DEV_SOLUTION_ID (the solutionid GUID captured from create-publisher-solution) as a GitHub repository variable using: gh variable set DEV_SOLUTION_ID --body "<guid>" --repo rpothin/mcdm26-ai-native-powerplatform-dev. Same rationale as the environment GUIDs: system-generated, not a name we chose, so it does not belong in a committed file. Ask-first since this touches GitHub repo settings.' WHERE id = 'persist-solution-id-github-var';

UPDATE todos SET description = 'Add docs/dev-solution-conventions.md documenting (a) human-chosen stable names -- solution unique name, solution display name, publisher display/unique name, publisher prefix -- and (b) the exact gh variable get DEV_ENVIRONMENT_URL / DEV_ENVIRONMENT_ID / DEV_SOLUTION_ID commands for resolving the system-generated GUIDs. Also update AGENTS.md with a new section that tells any future session, up front, exactly where Dev/solution context lives: the three GitHub repo variables for GUIDs, and this doc for the stable names -- so a new session resolves both sources before invoking solution-management instead of asking the user again.' WHERE id = 'document-conventions';

